import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BN3Eol-0.js";const f=JSON.parse('{"title":"UXD-007 — A site panorama opens facing the real photo, not the generated fill","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-007-panorama-opens-facing-the-photo.md","filePath":"uxs/decisions/UXD-007-panorama-opens-facing-the-photo.md"}'),i={name:"uxs/decisions/UXD-007-panorama-opens-facing-the-photo.md"};function r(s,e,d,h,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="uxd-007-—-a-site-panorama-opens-facing-the-real-photo-not-the-generated-fill" tabindex="-1">UXD-007 — A site panorama opens facing the real photo, not the generated fill <a class="header-anchor" href="#uxd-007-—-a-site-panorama-opens-facing-the-real-photo-not-the-generated-fill" aria-label="Permalink to &quot;UXD-007 — A site panorama opens facing the real photo, not the generated fill&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (the operator&#39;s point and clarification, then the go)</li><li><strong>Decider</strong>: the operator raised the point (W6, <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 271: &quot;Stand here&quot; must always show an image) and clarified it from the screen (line 452: the view opens facing the generated fill and &quot;the operator has to rotate to find the real photo&quot;). The fix described below is the lead&#39;s resolution (plan lines 452–455). The operator, 2026-11-11 (session go after the UXD check), recorded in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, line starting &quot;- Operator go, 2026-11-11 (session&quot; (line 460): the fixes for W6, SN2, G5/G6 and O6 &quot;are accepted as decided&quot;.</li><li><strong>Answers</strong>: W6; slice D2 (panel order for sites and orbiters)</li><li><strong>Changes</strong>: UXS-006 and the surface spec set (no panorama section exists yet; see UXS-000 §Next); ADR-074 (panorama schema and renderer) is the architecture record, not changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A panorama can be partial: a real photo over part of the sphere, and a generated fill that pads the rest. Inside &quot;Stand here&quot; the view opens facing the generated fill, so the visitor sees graphics and has to rotate to find the real photo (plan lines 271 and 452).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The sources record one fix and no alternatives.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The panorama <strong>opens facing the centre of the real photo region</strong>: a per-site initial heading derived from the panorama&#39;s photo span, on <strong>every site that has a panorama</strong>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><p>Slice D2 adds the per-site initial heading and an e2e asserting the initial view centre is inside the photo span (plan line 455). The same slice puts a photo first on every site panel and gives orbiters a &quot;Details&quot; tab (plan line 362).</p></li><li><p>Applies to every body with panoramas, not only the sites the operator looked at (<a href="./UXD-011-decisions-apply-project-wide">UXD-011</a>).</p></li><li><p>Slice D2 found the heading already built (v0.9.5, <code>entry_yaw_deg</code>) and did not add one; &quot;a photo first on every site&quot; was already true for the Moon and Mars (the hero is the first gallery image; <a href="./UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a>).</p></li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Written in slice D2 (<a href="./UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a>): <code>src/lib/panorama-entry.data.test.ts</code> checks every partial panorama&#39;s opening yaw against its <code>panorama_metadata.photo_span_deg</code>, and <code>tests/e2e/panorama-entry.spec.ts</code> reads the camera yaw the user gets (the compass rose&#39;s <code>data-yaw</code>) on the 18 partial panoramas, on desktop-chromium, mobile-chromium and mobile-landscape-chromium. The audit of the 30 is in UXD-034: one site (Insight) opened badly and was fixed, and a fly-in still running when &quot;Stand here&quot; was pressed overwrote the opening view on three sites until <code>enterPanorama</code> ended it.</p>',12)])])}const u=a(i,[["render",r]]);export{f as __pageData,u as default};
